WITH filtered AS (SELECT *, CONCAT_WS(',', method, status) AS method_status_key, COALESCE(method, 'NONE') AS resolved_method FROM payments WHERE paid_at >= TIMESTAMP '2023-08-18 17:00:00' AND order_id IS NOT NULL) SELECT id, order_id, status, AVG(amount) OVER (PARTITION BY method ORDER BY paid_at, id ROWS BETWEEN 3 PRECEDING AND CURRENT ROW) AS amount_avg_3, ROW_NUMBER() OVER (ORDER BY amount, id) AS row_seq, SUM(amount) OVER (PARTITION BY order_id ORDER BY paid_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_amount, AVG(amount) OVER w_recent AS amount_avg_3_prior FROM filtered WINDOW w_recent AS (PARTITION BY YEAR(paid_at), order_id ORDER BY amount, id ROWS BETWEEN 3 PRECEDING AND 1 PRECEDING)
